"""Held-out test trajectories per environment, generated by a random policy independent of all agents.

Each transition is tagged with the on-clauses that fired for the first time in that trajectory at that step
(Autumn.cpp only exposes cumulative coverage, so later firings of the same clause are untagged).
"""
import json
import os
import random

from autumn_env import BG, MOVES, AutumnEnv, apply_action, render

N_TRAJ, T = 6, 25


def gen(env_name, seed=777):
    env = AutumnEnv(env_name)
    rng = random.Random(seed)
    trajs, union = [], set()
    for k in range(N_TRAJ):
        it = env._new()
        g = render(it)
        init, steps, tags = g, [], []
        cov = set(it.get_covered_on_clause_indices())
        for t in range(T):
            kind = rng.choice(list(MOVES) + ["noop", "click_obj", "click_any"])
            if kind == "click_obj":
                cells = [(x, y) for y in range(env.H) for x in range(env.W) if g[y][x] != BG]
                x, y = rng.choice(cells) if cells else (rng.randrange(env.W), rng.randrange(env.H))
                a = f"click {x} {y}"
            elif kind == "click_any":
                a = f"click {rng.randrange(env.W)} {rng.randrange(env.H)}"
            else:
                a = kind
            apply_action(it, a)
            g = render(it)
            c2 = set(it.get_covered_on_clause_indices())
            steps.append((a, g))
            tags.append(sorted(c2 - cov))
            cov = c2
        union |= cov
        trajs.append(dict(init=init, steps=steps, tags=tags))
    return dict(env=env_name, n_clauses=env.n_clauses, random_policy_coverage=sorted(union), trajectories=trajs)


def load_or_make(env_name, d):
    path = os.path.join(d, f"heldout_{env_name}.json")
    if not os.path.exists(path):
        os.makedirs(d, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(gen(env_name), f)
    with open(path) as f:
        return json.load(f)
